@page "/board"
@using sv_84b66d5080e6408f9fba9da1bdfff52e.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p><em>Loading tasks...</em></p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <!-- Summary Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item">Total: <strong>@tasks.Count</strong></span>
        <span class="stat-item">To Do: <strong>@TodoTasks.Count()</strong></span>
        <span class="stat-item">In Progress: <strong>@InProgressTasks.Count()</strong></span>
        <span class="stat-item">Done: <strong>@DoneTasks.Count()</strong></span>
        <span class="stat-item stat-overdue">Overdue: <strong>@OverdueCount</strong></span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="board-container">
        @foreach (var column in Columns)
        {
            var columnTasks = GetFilteredTasksForColumn(column.Status);
            var showForm = activeFormColumn == column.Status;

            <div class="board-column">
                <div class="column-header">
                    <h3>@column.Name</h3>
                    <span class="badge bg-secondary">@columnTasks.Count</span>
                </div>

                <div class="column-body">
                    @foreach (var task in columnTasks)
                    {
                        <div class="task-card">
                            <div class="task-title">@task.Title</div>
                            <div class="task-assignee">@task.Assignee</div>
                            <span class="badge priority-badge @GetPriorityClass(task.Priority)">
                                @task.Priority
                            </span>
                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                            <div class="task-actions">
                                @if (column.LeftStatus is not null)
                                {
                                    var leftStatus = column.LeftStatus;
                                    <button class="btn btn-sm btn-outline-secondary"
                                            disabled="@isMoving"
                                            @onclick="() => MoveTaskAsync(task.Id, leftStatus)">
                                        &larr; Move Left
                                    </button>
                                }
                                @if (column.RightStatus is not null)
                                {
                                    var rightStatus = column.RightStatus;
                                    <button class="btn btn-sm btn-outline-secondary"
                                            disabled="@isMoving"
                                            @onclick="() => MoveTaskAsync(task.Id, rightStatus)">
                                        Move Right &rarr;
                                    </button>
                                }
                            </div>
                        </div>
                    }

                    @if (showForm)
                    {
                        <div class="add-task-form">
                            <input type="text" class="form-control mb-1" placeholder="Title"
                                   @bind="newTitle" />
                            <input type="text" class="form-control mb-1" placeholder="Assignee"
                                   @bind="newAssignee" />
                            <select class="form-select mb-1" @bind="newPriority">
                                <option value="High">High</option>
                                <option value="Medium">Medium</option>
                                <option value="Low">Low</option>
                            </select>
                            <input type="date" class="form-control mb-1" @bind="newDueDate" />
                            <div class="form-buttons">
                                <button class="btn btn-sm btn-primary" disabled="@isSaving"
                                        @onclick="() => SaveTaskAsync(column.Status)">
                                    Save
                                </button>
                                <button class="btn btn-sm btn-secondary" @onclick="CancelForm">
                                    Cancel
                                </button>
                            </div>
                        </div>
                    }
                </div>

                @if (!showForm)
                {
                    <button class="btn btn-sm btn-outline-primary add-task-btn"
                            @onclick="() => ShowForm(column.Status)">
                        + Add Task
                    </button>
                }
            </div>
        }
    </div>
}

