@code {
    private record ColumnDef(string Name, string Status, string? LeftStatus, string? RightStatus);

    private static readonly ColumnDef[] Columns =
    [
        new("To Do", "Todo", null, "InProgress"),
        new("In Progress", "InProgress", "Todo", "Done"),
        new("Done", "Done", "InProgress", null)
    ];

    private List<TaskItem> tasks = [];
    private bool isLoading = true;
    private bool isMoving;
    private bool isSaving;
    private string? errorMessage;
    private string searchText = string.Empty;

    // Form state
    private string? activeFormColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);

    private IEnumerable<TaskItem> TodoTasks => tasks.Where(t => t.Status == "Todo");
    private IEnumerable<TaskItem> InProgressTasks => tasks.Where(t => t.Status == "InProgress");
    private IEnumerable<TaskItem> DoneTasks => tasks.Where(t => t.Status == "Done");
    private int OverdueCount => tasks.Count(t => t.DueDate < DateTime.Today);

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasksForColumn(string status)
    {
        var columnTasks = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            columnTasks = columnTasks.Where(t =>
                t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return columnTasks.ToList();
    }

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        try
        {
            isMoving = true;
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = tasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                tasks[idx] = tasks[idx] with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
        finally
        {
            isMoving = false;
        }
    }

    private void ShowForm(string columnStatus)
    {
        activeFormColumn = columnStatus;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelForm()
    {
        activeFormColumn = null;
    }

    private async Task SaveTaskAsync(string status)
    {
        if (string.IsNullOrWhiteSpace(newTitle))
            return;

        try
        {
            isSaving = true;
