.stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 0.75rem 1rem;
    background: var(--bs-light, #f8f9fa);
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat-item {
    font-size: 0.95rem;
}

.stat-overdue strong {
    color: #dc3545;
}

.search-bar {
    margin-bottom: 1rem;
    max-width: 400px;
}

.board-container {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    min-width: 250px;
    background: var(--bs-light, #f8f9fa);
    border-radius: 0.5rem;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
}

.column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.column-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 100px;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.task-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.task-assignee {
    font-size: 0.85rem;
    color: #6c757d;
    margin-bottom: 0.25rem;
}

.task-due {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.priority-badge {
    font-size: 0.75rem;
}

.priority-high {
    background-color: #dc3545 !important;
    color: #fff;
}

.priority-medium {
    background-color: #ffc107 !important;
    color: #000;
}

.priority-low {
    background-color: #198754 !important;
    color: #fff;
}

.task-actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.add-task-btn {
    margin-top: 0.5rem;
    width: 100%;
}

.add-task-form {
    background: #fff;
    border: 1px dashed #adb5bd;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.form-buttons {
    display: flex;
    gap: 0.5rem;
}

